// n8n ya detectó y parseó el JSON, así que tomamos el objeto directamente:
let datos_extraidos = $input.first().json;

// Definir los campos que queremos monitorear
const campos_a_revisar = ["categoria", "tipo_lugar", "lugar", "fecha_evento", "hora_evento"];
let campos_faltantes = [];

// Lógica 100% precisa: si el valor es nulo o no existe, se añade a la lista
for (let campo of campos_a_revisar) {
  if (datos_extraidos[campo] === null || datos_extraidos[campo] === undefined) {
    campos_faltantes.push(campo);
  }
}

// Agregar el arreglo calculado al objeto final
datos_extraidos.campos_faltantes = campos_faltantes;

// Retornar en el formato estándar de un item en n8n
return { json: datos_extraidos };
